    result = [[0] * cols for _ in range(rows)]

    # Find 2-block
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 2:
                if all(grid[r+dr][c+dc] == 2 for dr in [0, 1] for dc in [0, 1] if 0 <= r+dr < rows and 0 <= c+dc < cols):
