                        for dc in [0, 1]:
                            result[r+dr][c+dc] = 2

    # For each non-2 value, determine if it goes to main or anti-diagonal
    # Collect all values
    non2_values = []
    for r in range(rows):
        for c in range(cols):
            v = grid[r][c]
            if v != 0 and v != 2:
                dist_main = abs(r - c)
                non2_values.append((v, r, c, dist_main))

    # Sort by dist_main: close ones go to anti, far ones go to main
    close_vals = [v for v in non2_values if v[3] <= 2]
    far_vals = [v for v in non2_values if v[3] > 2]

    print(f"Close values (<=2 from main diag): {[(v, r+c) for v in close_vals]}")
    print(f"Far values (>2 from main diag): {[(v, r+c) for v in far_vals]}")

    # Fill close values on anti-diagonal r+c=7
    for v, r, c, _ in close_vals:
        # Find available positions on r+c=7
        for nr in range(rows):
            nc = 7 - nr
            if 0 <= nc < cols and result[nr][nc] == 0:
                result[nr][nc] = v
                break

    # Fill far values on main diagonal
    for v, r, c, _ in far_vals:
        # Find available positions on main diagonal (r=c)
        for nr in range(max(r, c), rows):  # start from max(r,c)
            nc = nr
            if 0 <= nc < cols and result[nr][nc] == 0:
                result[nr][nc] = v
                break

    return result

