def transform_simple(grid):
    rows, cols = len(grid), len(grid[0])
    result = [[0] * cols for _ in range(rows)]

    # Find 4 positions where grid[r][c]=2 for a 2x2 block
    block_found = False
    for r in range(rows):
        for c in range(cols):
            if r < rows-1 and c < cols-1:
                is_block = (grid[r][c] == 2 and grid[r][c+1] == 2 
                           and grid[r+1][c] == 2 and grid[r+1][c+1] == 2)
                if is_block:
                    for dr in [0, 1]:
                        for dc in [0, 1]:
                            result[r+dr][c+dc] = 2
                    block_found = True
                    break
            if block_found:
                break
        if block_found:
            break

    # Collect all non-2 values
    non2_values = []
    for r in range(rows):
        for c in range(cols):
            v = grid[r][c]
            if v != 0 and v != 2:
                dist_main = abs(r - c)
                non2_values.append((v, r, c, dist_main))

    # Sort values: first by distance (closer goes to anti-diag, farther to main), then by r+c
    non2_values.sort(key=lambda x: (x[3], x[0] + x[1]))

    # Separate into close (dist <= 2) and far (dist > 2)
    close_vals = [v for v in non2_values if v[3] <= 2]
    far_vals = [v for v in non2_values if v[3] > 2]

    # Fill close values on anti-diagonal r+c=7
    for v, r, c, _ in close_vals:
        for nr in range(rows):
            nc = 7 - nr
            if 0 <= nc < cols and result[nr][nc] == 0:
                result[nr][nc] = v
                break

    # Fill far values on main diagonal starting from their original position
    for v, r, c, _ in far_vals:
        start_r = max(r, c)
        for nr in range(start_r, rows):
            nc = nr
            if 0 <= nc < cols and result[nr][nc] == 0:
                result[nr][nc] = v
                break

    return result

