# Test the transform
def transform_simple(model_grid):
    rows, cols = len(model_grid), len(model_grid[0])

    output = [[0]*cols for _ in range(rows)]

    # Fill 2-block
    for dr in [0, 1]:
        for dc in [0, 1]:
            output[block_r + dr][block_c + dc] = 2

    # Process non-2 values
    non2_values = [(v, r, c) for r in range(rows) for c in range(cols) if model_grid[r][c] != 0 and model_grid[r][c] != 2]

    for v, r, c in non2_values:
        region = get_region(r, c, block_r, block_c)

        if region == "TL":
            for i in range(rows):
                nr, nc = i, anti_diag_sum - i
                if 0 <= nc < cols and output[nr][nc] == 0:
