                nr, nc = i, i  
                if 0 <= nc < cols and output[nr][nc] == 0:
                    output[nr][nc] = v
                    break
        elif region == "TR":
            for i in range(rows - max(r, c), rows):
                nr, nc = max(r, c) + (i), max(r, c) + (i)
                if 0 <= nr < rows and 0 <= nc < cols and output[nr][nc] == 0:
                    output[nr][nc] = v
                    break
        elif region == "BR":
            start_r = r
            start_c = anti_diag_sum - start_r
            for i in range(rows - start_r):
                nr, nc = start_r + i, anti_diag_sum - (start_r + i)
                if 0 <= nc < cols and output[nr][nc] == 0:
                    output[nr][nc] = v
                    break

